namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();

    private readonly string[] _templates =
    [
        "New comment on your post",
        "Your build succeeded",
        "Deployment to production completed",
        "New follower: user_{0}",
        "Pull request #{0} merged",
        "Issue #{0} was closed",
        "Security alert resolved",
        "Scheduled maintenance in 1 hour",
        "Your export is ready to download",
        "Team member joined your project"
    ];

    public List<NotificationItem> GetInitialNotifications()
    {
        lock (_lock)
        {
            return Enumerable.Range(0, 5).Select(_ => GenerateNotification()).ToList();
        }
    }

    public List<NotificationItem> CheckForNew()
    {
        lock (_lock)
        {
            // Simulate ~30% chance of a new notification each poll
            if (Random.Shared.Next(100) < 30)
            {
                return [GenerateNotification()];
            }
            return [];
        }
    }

    private NotificationItem GenerateNotification()
    {
        var template = _templates[Random.Shared.Next(_templates.Length)];
        var message = string.Format(template, Random.Shared.Next(1000));
        return new NotificationItem
        {
            Id = _nextId++,
            Message = message,
            Timestamp = DateTime.UtcNow
        };
    }
}

